"use client";
import { Dispatch, SetStateAction, useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { Button } from "@/client/components/ui/button";
import { Form } from "@/client/components/ui/form";
import { CustomFormField } from "./FormField";
import { Loader2, Plus } from "lucide-react";
import ResponsiveDialog from "./ResponsiveDialog";
import Image from "@/node_modules/next/image";
import { Card } from "@/client/components/ui/card";

const imageFormSchema = z.object({
  imageUrl: z.array(z.instanceof(File)).optional(),
});

type Image = {
  imageURL: string;
};

const CreateImageForm = ({
  setIsImageModalOpen,
  setImages,
}: {
  setIsImageModalOpen: Dispatch<SetStateAction<boolean>>;
  setImages: Dispatch<SetStateAction<Image[]>>;
}) => {
  const form = useForm<z.infer<typeof imageFormSchema>>({
    resolver: zodResolver(imageFormSchema),
    defaultValues: {
      images: [],
    },
  });

  // const uploadToS3 = (file) => {
  // get presigned url
  // post to s3 with presigned url
  // get the s3 url and deconstruct
  // return permanent s3 url
  // return url
  // }

  const onSubmit = async (values: z.infer<typeof imageFormSchema>) => {
    // get presigned s3 url, upload image to s3, get the s3 url and store it in images
    // uploadToS3(values)
    setImages((prev) => [...prev, values]);
    setIsImageModalOpen(false);
  };
  useEffect(() => {
    const subscription = form.watch((value) => {
      console.log(value);
    });
    return () => subscription.unsubscribe();
  }, [form]);

  const isLoading = form.formState.isSubmitting;
  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="w-full">
        <CustomFormField name="images" label="" type="file" accept="image/*" />
        {/* SUBMIT BUTTON - adds a produt json to the order summary list*/}
        <div className="col-span-4 flex justify-end mr-2 mt-2">
          <Button
            type="submit"
            disabled={isLoading}
            className="w-full sm:w-auto"
          >
            {isLoading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Creating...
              </>
            ) : (
              "Create"
            )}
          </Button>
        </div>
      </form>
    </Form>
  );
};

const formSchema = z.object({
  name: z.string().min(1, "Name is required"),
  type: z.string().min(1, "Type is required"),
  style: z.string().min(1, "Style is required"),
  size: z.string().min(1, "Size is required"),
  price: z.coerce.number(),
  stock: z.coerce.number(),
  // Images
  images: z.array(imageFormSchema).min(1, "At least one image is required"),
  // Files
  //   measurementPdf: z.array(z.instanceof(File)).optional(), // single file
  //   additionalFiles: z.array(z.instanceof(File)).optional(), // multiple files
});

const Item = ({ imageUrl }) => {
  return (
    <Card>
      <div>delete button</div>
      <Image src={imageUrl} alt="image" width={50} height={50} />;
      {/* add a tag */}
      <div>Tag</div>
    </Card>
  );
};

const CreateForm = ({
  setIsOpen,
}: {
  setIsOpen: Dispatch<SetStateAction<boolean>>;
}) => {
  const [isCreateImageFormOpen, setCreateImageFormOpen] = useState(false);
  const [images, setImages] = useState<Image[]>([]);

  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      name: "",
      type: "",
      style: "",
      size: "",
      price: 0,
      stock: 0,
      images: [],
      //   additionalFiles: [],
    },
  });

  useEffect(() => {
    const subscription = form.watch((value) => {
      console.log(value);
    });
    return () => subscription.unsubscribe();
  }, [form]);

  useEffect(() => {
    form.setValue("images", images);
  }, [images, form]);

  const isLoading = form.formState.isSubmitting;

  const onSubmit = async (values: z.infer<typeof formSchema>) => {
    setIsOpen(false);
  };

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit(onSubmit)}
        className="grid grid-cols-1 gap-6 sm:px-0 px-4 w-full"
      >
        <CustomFormField name="name" label="Name" type="" />
        <CustomFormField name="type" label="Type" type="" />
        <CustomFormField name="style" label="Style" type="" />
        <CustomFormField name="size" label="Size" type="" />
        <CustomFormField name="price" label="Price" type="number" />
        <CustomFormField name="stock" label="Stock" type="number" />
        <div>Images</div>
        {images.length > 0 ? (
          images.map((image, index) => <Item key={index} {...image} />)
        ) : (
          <div>No images in this order</div>
        )}
        <ResponsiveDialog
          isOpen={isCreateImageFormOpen}
          setIsOpen={setCreateImageFormOpen}
          title="Add Images"
          description=""
        >
          <CreateImageForm
            setIsImageModalOpen={setCreateImageFormOpen}
            setImages={setImages}
          />
        </ResponsiveDialog>
        <Button
          type="button"
          variant="ghost"
          className="h-8 w-8 p-0 flex items-center rounded-md bg-white shadow-md hover:bg-gray-100"
          onClick={() => {
            setCreateImageFormOpen(true);
          }}
        >
          <Plus className="h-4 w-4" />
        </Button>
        <div className="flex w-full sm:justify-end">
          <Button
            type="submit"
            disabled={isLoading}
            className="w-full sm:w-auto shadow-lg hover:bg-black hover:text-white bg-white text-black"
          >
            {isLoading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Creating...
              </>
            ) : (
              "Create"
            )}
          </Button>
        </div>
      </form>
    </Form>
  );
};

export default CreateForm;
